    }

    .icons {
      float: left;
      text-align: center;
      margin: 0 0 0 5px;
      list-style: none;

      > li {
        float: left;
      }
      .icon {
        display: block;
        padding: 3px;
        color: scale-color($header_primary, $lightness: 50%);
        text-decoration: none;
        cursor: pointer;
        border-top: 1px solid transparent;
        border-left: 1px solid transparent;
        border-right: 1px solid transparent;
        transition: all linear .15s;


        &:hover {
          color: $primary;
          background-color:  dark-light-diff($primary, $secondary, 90%, -60%);
          border-top: 1px solid transparent;
          border-left: 1px solid transparent;
          border-right: 1px solid transparent;
        }
        &:active {
          color: $primary;
          background-color: dark-light-diff($primary, $secondary, 90%, -60%);
        }
      }
      .active .icon {
        position: relative;
        color: #7b7b7b;
        background-color: $secondary;
        cursor: default;
        border-top: 1px solid dark-light-diff($primary, $secondary, 90%, -60%);
        border-left: 1px solid dark-light-diff($primary, $secondary, 90%, -60%);
        border-right: 1px solid dark-light-diff($primary, $secondary, 90%, -60%);
        &:after {
          display: block;
          position: absolute;
          top: 100%;
          left: 0;
          z-index: 1101;
          width: 100%;
          height: 0;
          content: "";
          border-top: 1px solid $secondary;
        }
        &:hover {
        border-bottom: none;
        }
      }
      [class^="fa fa-"] {
        width: 32px;
        height: 32px;
        font-size: 1.714em;
        line-height: 32px;
        display: inline-block;
      }
      .notifications {
        position: relative;
      }
      .badge-notification {
        position: absolute;
        top: -9px;
        z-index: 1;
        margin-left: 0;
      }
      .unread-notifications {
        right: -4px;
        background-color: scale-color($tertiary, $lightness: 50%);
      }
      .unread-private-messages {
        left: -4px;
      }
    }
    .flagged-posts {
      background: $danger;
    }
}
